#include "serialtools.hpp"
#include "language.hpp"
#ifdef Q_OS_WIN
#define THINKCAD_PORT_ADDRESS(info) (info).portName()
#else
#define THINKCAD_PORT_ADDRESS(info) (info).systemLocation()
#endif
#include <QSerialPortInfo>
#include <QComboBox>
#include <QPlainTextEdit>
#include <QLineEdit>
#include <QPushButton>
#include <QTabWidget>
#include <QHBoxLayout>
#include <QVBoxLayout>
#include <QLabel>
#include <QTextCursor>
#include <QPainter>
#include <QPainterPath>
#include <QEvent>
#include <QRegularExpression>
#include <cmath>
#include <QSet>
SerialTools::SerialTools(QWidget* parent):QWidget(parent){setObjectName("serialTools");clock_.start();auto* layout=new QVBoxLayout(this);auto* controls=new QHBoxLayout;source_=new QComboBox;source_->setObjectName("serialSource");source_->addItem(Language::text("Echtes Gerät"),"hardware");controls->addWidget(source_);ports_=new QComboBox;ports_->setEditable(true);ports_->setObjectName("serialPort");ports_->setMinimumContentsLength(12);controls->addWidget(ports_);auto* refresh=new QPushButton(Language::text("Ports aktualisieren"));controls->addWidget(refresh);baud_=new QComboBox;for(int rate:{9600,19200,38400,57600,115200,230400,460800,921600})baud_->addItem(QString::number(rate),rate);baud_->setCurrentText("115200");controls->addWidget(baud_);connect_=new QPushButton(Language::text("Verbinden"));connect_->setObjectName("serialConnect");controls->addWidget(connect_);layout->addLayout(controls);tabs_=new QTabWidget;monitor_=new QPlainTextEdit;monitor_->setObjectName("serialMonitor");monitor_->setReadOnly(true);monitor_->setMaximumBlockCount(10000);tabs_->addTab(monitor_,Language::text("Serieller Monitor"));plot_=new QWidget;plot_->setObjectName("serialPlotter");plot_->setMinimumHeight(150);plot_->installEventFilter(this);tabs_->addTab(plot_,Language::text("Serieller Plotter"));layout->addWidget(tabs_);auto* sendRow=new QHBoxLayout;input_=new QLineEdit;input_->setObjectName("serialInput");input_->setPlaceholderText(Language::text("Text an ausgewähltes Gerät senden"));sendRow->addWidget(input_,1);ending_=new QComboBox;ending_->addItems({"LF","CRLF","CR",Language::text("Kein Zeilenende")});sendRow->addWidget(ending_);auto* sendButton=new QPushButton(Language::text("Senden"));sendRow->addWidget(sendButton);auto* clear=new QPushButton(Language::text("Leeren"));sendRow->addWidget(clear);layout->addLayout(sendRow);
connect(refresh,&QPushButton::clicked,this,&SerialTools::refreshPorts);connect(sendButton,&QPushButton::clicked,this,&SerialTools::send);connect(input_,&QLineEdit::returnPressed,this,&SerialTools::send);connect(clear,&QPushButton::clicked,this,[this]{monitor_->clear();points_.clear();pending_.clear();plot_->update();});connect(connect_,&QPushButton::clicked,this,[this]{if(port_.isOpen()){closePort();return;}port_.setPortName(ports_->currentText().trimmed());port_.setBaudRate(baud_->currentText().toInt());if(!port_.open(QIODevice::ReadWrite)){emit notice(port_.errorString());return;}port_.setDataTerminalReady(true);connect_->setText(Language::text("Trennen"));});connect(&port_,&QSerialPort::readyRead,this,[this]{receive("hardware",port_.readAll(),clock_.elapsed()/1000.0);});connect(&port_,&QSerialPort::errorOccurred,this,[this](QSerialPort::SerialPortError error){if(error==QSerialPort::ResourceError){emit notice(port_.errorString());closePort();}});connect(source_,qOverload<int>(&QComboBox::currentIndexChanged),this,[this]{bool hardware=source_->currentData()=="hardware";ports_->setEnabled(hardware);baud_->setEnabled(hardware);connect_->setEnabled(hardware);});refreshPorts();}
void SerialTools::refreshPorts(){auto current=ports_->currentData().toString();if(current.isEmpty())current=ports_->currentText();ports_->clear();for(const auto& info:QSerialPortInfo::availablePorts())ports_->addItem(THINKCAD_PORT_ADDRESS(info),THINKCAD_PORT_ADDRESS(info));int index=ports_->findData(current);if(index>=0)ports_->setCurrentIndex(index);else if(!current.isEmpty())ports_->setEditText(current);}
void SerialTools::boards(const QStringList& ids){const auto current=source_->currentData();source_->clear();source_->addItem(Language::text("Echtes Gerät"),"hardware");for(const auto& id:ids)source_->addItem("Simulation · "+id,id);source_->setCurrentIndex(std::max(0,source_->findData(current)));for(auto it=incoming_.begin();it!=incoming_.end();)if(!ids.contains(it.key()))it=incoming_.erase(it);else ++it;}
void SerialTools::closePort(){port_.close();connect_->setText(Language::text("Verbinden"));}
int SerialTools::available(const QString& board)const{return incoming_.value(board).size();}
int SerialTools::read(const QString& board,bool peek){auto& data=incoming_[board];if(data.isEmpty())return -1;int value=static_cast<unsigned char>(data.front());if(!peek)data.remove(0,1);return value;}
QString SerialTools::monitorText()const{return monitor_->toPlainText();}
void SerialTools::send(){auto bytes=input_->text().toUtf8();if(ending_->currentIndex()==0)bytes+='\n';else if(ending_->currentIndex()==1)bytes+="\r\n";else if(ending_->currentIndex()==2)bytes+='\r';const auto source=source_->currentData().toString();if(source=="hardware"){if(!port_.isOpen()){emit notice(Language::text("Zuerst seriellen Port verbinden."));return;}port_.write(bytes);}else{auto& data=incoming_[source];if(data.size()+bytes.size()>65536){emit notice(Language::text("Serieller Eingabepuffer voll."));return;}data+=bytes;}input_->clear();}
void SerialTools::receive(const QString& source,const QByteArray& data,double seconds){monitor_->moveCursor(QTextCursor::End);monitor_->insertPlainText(QString::fromUtf8(data));auto& pending=pending_[source];pending+=data;if(pending.size()>65536)pending.remove(0,pending.size()-65536);int newline;while((newline=pending.indexOf('\n'))>=0){auto line=QString::fromUtf8(pending.left(newline)).trimmed();pending.remove(0,newline+1);Point point{seconds,{}};int index=0;for(const auto& token:line.split(QRegularExpression("[,;\\s]+"),Qt::SkipEmptyParts)){const auto colon=token.indexOf(':');QString name=colon>0?token.left(colon):"value"+QString::number(index++);bool ok=false;double value=(colon>0?token.mid(colon+1):token).toDouble(&ok);if(ok&&std::isfinite(value)&&point.values.size()<16)point.values[source+"/"+name]=value;}if(!point.values.isEmpty()){points_.push_back(std::move(point));while(points_.size()>2000)points_.pop_front();}}plot_->update();}
bool SerialTools::eventFilter(QObject* object,QEvent* event){if(object==plot_&&event->type()==QEvent::Paint){QPainter painter(plot_);paintPlot(painter,plot_->rect());return true;}return QWidget::eventFilter(object,event);}
void SerialTools::paintPlot(QPainter& p,QRect rect){p.fillRect(rect,QColor("#101c29"));if(points_.empty()){p.setPen(Qt::white);p.drawText(rect,Qt::AlignCenter,Language::text("Zahlen oder name:wert senden, z. B. Spannung:3.3 Strom:0.02"));return;}QRectF area=QRectF(rect).adjusted(55,25,-15,-25);double minimum=0,maximum=1;QSet<QString> channels;for(const auto& point:points_)for(auto it=point.values.begin();it!=point.values.end();++it){minimum=std::min(minimum,it.value());maximum=std::max(maximum,it.value());channels.insert(it.key());}double first=points_.front().time,span=std::max(.001,points_.back().time-first),range=std::max(.001,maximum-minimum);const QColor colors[]={QColor("#facc15"),QColor("#38bdf8"),QColor("#4ade80"),QColor("#f472b6")};QStringList sorted(channels.begin(),channels.end());sorted.sort();int i=0;for(const auto& channel:sorted){QPainterPath path;bool started=false;for(const auto& point:points_){if(!point.values.contains(channel))continue;QPointF xy(area.left()+(point.time-first)/span*area.width(),area.bottom()-(point.values[channel]-minimum)/range*area.height());if(started)path.lineTo(xy);else path.moveTo(xy);started=true;}p.setPen(QPen(colors[i%4],1.5));p.drawPath(path);p.drawText(60+i*140,17,channel);++i;}p.setPen(Qt::white);p.drawText(2,area.top()+10,QString::number(maximum,'g',4));p.drawText(2,area.bottom(),QString::number(minimum,'g',4));p.drawText(area.adjusted(0,area.height(),0,20),Qt::AlignRight,QString("%1 s").arg(points_.back().time,0,'f',3));}
